#!/usr/bin/env python3
"""Generate docs/catalog.md: every rule and skill, its category, and its
description, read from `install.sh --list --json` (which reads the
frontmatter). The counts in the catalog come from the same data, so they
can't drift from what the installer ships.

    python3 .github/scripts/generate-catalog.py          # rewrite docs/catalog.md
    python3 .github/scripts/generate-catalog.py --check  # exit 1 if it's stale
"""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[2]
CATALOG = REPO_ROOT / "docs" / "catalog.md"

# Skill names don't carry a platform prefix as consistently as rule names.
APPLE_SKILL_PREFIXES = ("swift", "coredata-", "app-intents-", "instruments-", "xcode-")
ANDROID_SKILL_PREFIXES = ("android-", "r8-", "xml-to-compose-")


def platform_of_rule(filename: str) -> str:
    if filename.startswith("apple-"):
        return "Apple"
    if filename.startswith("android-"):
        return "Android"
    return "Cross-platform"


def platform_of_skill(name: str) -> str:
    if name.startswith(APPLE_SKILL_PREFIXES):
        return "Apple"
    if name.startswith(ANDROID_SKILL_PREFIXES):
        return "Android"
    return "Cross-platform"


def load() -> dict:
    out = subprocess.run(
        ["bash", str(REPO_ROOT / "install.sh"), "--list", "--json",
         "--platform", "both", "--apple-language", "both", "--features", "all",
         "--apple-platforms", "all", "--android-platforms", "all"],
        check=True, capture_output=True, text=True,
    ).stdout
    return json.loads(out)


def cell(text: str | None) -> str:
    return (text or "").replace("|", "\\|").replace("\n", " ").strip()


def render(data: dict) -> str:
    recommended = {c["name"] for c in data["categories"] if c["recommended"]}
    platforms = ("Apple", "Android", "Cross-platform")
    rules = {p: [] for p in platforms}
    for r in data["rules"]:
        rules[platform_of_rule(r["filename"])].append(r)
    skills = {p: [] for p in platforms}
    for s in data["skills"]:
        skills[platform_of_skill(s["name"])].append(s)

    def counts(groups: dict) -> str:
        return ", ".join(f"{len(groups[p])} {p}" for p in platforms)

    lines = [
        "# Catalog",
        "",
        "<!-- Generated by .github/scripts/generate-catalog.py from the rule and skill",
        "     frontmatter. Don't edit by hand; CI fails when this file is stale. -->",
        "",
        f"**{len(data['rules'])} rules** ({counts(rules)}) and "
        f"**{len(data['skills'])} skills** ({counts(skills)}).",
        "",
        "Rules load automatically for the files they cover; skills are on-demand",
        "deep reviews (Claude Code). The category is what `--features` selects.",
        "Categories marked ★ are in the default `recommended` set.",
        "Run `./install.sh --list` to see what a given selection installs.",
        "",
        "## Categories",
        "",
        "| Category | Recommended | Rules | Skills |",
        "|---|---|---|---|",
    ]
    for c in data["categories"]:
        n_rules = sum(1 for r in data["rules"] if r["category"] == c["name"])
        n_skills = sum(1 for s in data["skills"] if s["category"] == c["name"])
        lines.append(f"| `{c['name']}` | {'★' if c['name'] in recommended else ''} | {n_rules} | {n_skills} |")

    for p in platforms:
        lines += ["", f"## {p}", "", f"### Rules ({len(rules[p])})", "",
                  "| Rule | Category | Description |", "|---|---|---|"]
        for r in sorted(rules[p], key=lambda r: r["filename"]):
            star = " ★" if r["category"] in recommended else ""
            lines.append(f"| [`{r['filename']}`](../.claude/rules/{r['filename']}) | `{r['category']}`{star} | {cell(r['description'])} |")
        lines += ["", f"### Skills ({len(skills[p])})", "",
                  "| Skill | Category | Description |", "|---|---|---|"]
        for s in sorted(skills[p], key=lambda s: s["name"]):
            star = " ★" if s["category"] in recommended else ""
            lines.append(f"| [`{s['name']}`](../.claude/skills/{s['name']}/SKILL.md) | `{s['category']}`{star} | {cell(s['description'])} |")
    return "\n".join(lines) + "\n"


def main() -> int:
    text = render(load())
    if "--check" in sys.argv[1:]:
        current = CATALOG.read_text(encoding="utf-8") if CATALOG.exists() else ""
        if current != text:
            print("docs/catalog.md is stale. Run: python3 .github/scripts/generate-catalog.py", file=sys.stderr)
            return 1
        print("docs/catalog.md is up to date.")
        return 0
    CATALOG.parent.mkdir(exist_ok=True)
    CATALOG.write_text(text, encoding="utf-8")
    print(f"Wrote {CATALOG.relative_to(REPO_ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
